build(ch, "magnets-forces-machines", "Magnets, forces and simple machines", 35,
    ["Say which materials a magnet attracts and what poles do.", "Describe push and pull forces, friction and gravity.", "Name simple machines and say how they make work easier."],
    [("key", "definition", "Magnets", "A **magnet** attracts objects made of **iron** and **steel** (they are called **magnetic**). It does not attract wood, plastic, glass or most other metals such as copper and aluminium. A magnet has two **poles**, **north** and **south**. **Unlike poles attract** (north and south). **Like poles repel** (north and north push apart)."),
     ("key", "definition", "Forces", "A **force** is a push or a pull. A force can start or stop an object, make it go faster or slower, change its direction or change its shape. **Gravity** pulls everything towards the centre of the Earth: it makes things fall and gives them **weight**. **Friction** is a force that slows moving things when two surfaces rub. It is useful for brakes and for walking, but it wears machines, so oil is used to reduce it."),
     ("fig", fig_lever, "A lever: a small effort on one side lifts a load on the other.", "A long bar rests on a triangle called the pivot. A blue load sits on the left end. A red arrow pushes down on the right end."),
     ("key", "retenir", "Simple machines", "A **simple machine** makes work easier (less effort, or a better direction). Examples: **lever** (see-saw, scissors, wheelbarrow, crowbar), **pulley** (raising water from a well, a flag), **inclined plane** (a ramp or a sloping road), **wheel and axle** (bicycle, cart), **wedge** (axe, knife) and **screw** (a bottle top, a jack)."),
     ("key", "pieges", "Common mistakes", "- Saying that a magnet attracts all metals. Only some metals (iron, steel) are magnetic.\n- Saying that like poles attract.\n- Believing that a machine **creates** energy: it only makes the work easier.\n- Mixing up weight (a force, from gravity) and mass (how much matter)."),
     ("ex", "Example 1", "A magnet is held near a nail, a coin made of copper, and a plastic ruler. Which will it attract?", ["The nail is made of iron (or steel): magnetic.", "Copper and plastic are not magnetic."], "Only the iron nail."),
     ("ex", "Example 2", "Why is it easier to push a heavy barrel up a ramp than to lift it?", ["A ramp is an inclined plane: it spreads the work over a longer distance.", "We need a smaller force, but we must push over a longer distance."], "A ramp (inclined plane) needs a smaller force, but over a longer distance.")],
    [M("application", "Which object will a magnet attract?", "an iron nail", ["a plastic ruler", "a wooden pencil", "a glass marble"], "Iron is magnetic."),
     M("application", "What happens when two north poles are brought together?", "they repel", ["they attract", "nothing happens", "they stick forever"], "Like poles repel."),
     M("application", "Which is a lever?", "a see-saw", ["a window", "a stone", "a rope only"], "A see-saw turns on a pivot."),
     TF("approfondissement", "Friction is a force that slows moving objects.", True, "Rubbing surfaces slow motion."),
     MA("approfondissement", "Match the machine with an example.", [("lever", "scissors"), ("inclined plane", "a ramp"), ("wheel and axle", "a bicycle wheel"), ("pulley", "raising a flag")], "Each is a simple machine."),
     P("A farmer wants to load heavy sacks of cocoa onto a truck. A boy suggests using a long wooden plank as a ramp.",
       [PM("What simple machine is the plank?", "inclined plane", ["pulley", "wedge", "lever"], "A sloping surface is an inclined plane."),
        PM("What is the advantage?", "less effort is needed", ["no effort is needed", "the sacks become lighter", "the truck gets bigger"], "A ramp reduces the force needed."),
        PM("Which force makes the sacks slide down the plank when released?", "gravity", ["magnetism", "friction only", "wind"], "Gravity pulls the sacks down.", points=2)])],
    [("A magnet has...", "two poles", ["one pole", "three poles", "no pole"], "North and south."),
     ("The force that pulls things to the ground is...", "gravity", ["friction", "magnetism", "wind"], "Gravity pulls towards the Earth."),
     ("Oil helps machines because it reduces...", "friction", ["gravity", "weight", "magnetism"], "Oil makes surfaces slide."),
     ("Which of these is NOT magnetic?", "copper", ["iron", "steel", "an iron nail"], "Copper is not attracted by a magnet."),
     ("A force is a...", "push or pull", ["colour", "sound", "kind of metal"], "That is the definition.")],
    ["Weight vs mass is only mentioned; unit of force (newton) is not covered. Check whether gravity/friction are in the Class 6 syllabus."],
    prereq=["fslc-science-matter-energy"])

fig_circ = shapes([LINE(80, 70, 320, 70, width=3), LINE(320, 70, 320, 170, width=3), LINE(320, 170, 80, 170, width=3), LINE(80, 170, 80, 70, width=3),
                   RECT(70, 100, 20, 40, fill="lightyellow"), T(110, 120, "cell", 14, bold=True, anchor="start"),
                   CIRCLE(200, 70, 22, fill="yellow"), T(200, 40, "bulb", 14, bold=True),
                   RECT(190, 160, 20, 20, fill="lightgrey"), T(200, 205, "switch", 14, bold=True)], 400, 225)
build(ch, "electricity-safety", "Electricity and electrical safety", 30,
    ["Describe a simple electric circuit and what a switch does.", "Tell conductors from insulators of electricity.", "Follow the safety rules for electricity."],
    [("key", "definition", "A simple circuit", "A **circuit** is a closed path for electricity. A simple circuit has a **cell** (or battery) that pushes the electricity, **wires** and a **bulb**. A **switch** opens or closes the path: when the switch is **closed** the bulb lights; when it is **open** the circuit is broken and the bulb goes out."),
     ("fig", fig_circ, "A simple circuit with a cell, a bulb and a switch.", "A rectangle of wire. On the left side there is a cell. At the top is a bulb. At the bottom is a switch."),
     ("key", "definition", "Conductors and insulators", "**Conductors** let electricity pass: copper, iron, aluminium and other metals. **Insulators** do not: plastic, rubber, dry wood, glass and cloth. Wires are made of metal (conductor) covered with plastic (insulator). **Water that is not pure** and the **human body** also conduct electricity, so they are dangerous near electricity."),
     ("key", "methode", "Safety rules", "- Never touch bare wires, sockets or switches with **wet hands**.\n- Never put fingers, pins or metal into a socket.\n- Do not play with electric wires, and **stay away from fallen power lines**: tell an adult at once.\n- Do not fly kites near power lines or climb electricity poles.\n- Do not plug too many things into one socket.\n- Let an adult unplug broken equipment. During a storm, stay inside and do not shelter under a tall tree."),
     ("key", "pieges", "Common mistakes", "- Thinking a bulb lights with only one wire connected: the circuit must be a **complete loop**.\n- Using a pin or knife to take out a plug.\n- Saying that all metals are magnetic or that all materials conduct: plastic and rubber are insulators.\n- Using a damaged cable because it 'still works'."),
     ("ex", "Example 1", "A bulb does not light in a circuit with a cell, wires and a switch. Give two possible reasons.", ["The switch is open, so the circuit is not complete.", "A wire is loose or broken, or the cell is flat."], "The switch may be open, or a wire may be loose or the cell flat."),
     ("ex", "Example 2", "Why are electric wires covered with plastic?", ["The wire inside is metal and carries the electricity.", "Plastic is an insulator, so it protects us from the electricity."], "Plastic is an insulator, so it protects us from shock.")],
    [M("application", "Which material is an electrical insulator?", "rubber", ["copper", "iron", "aluminium"], "Rubber does not let electricity pass."),
     M("application", "What does a closed switch do?", "completes the circuit so the bulb lights", ["breaks the circuit", "turns off the cell", "makes the wire insulating"], "The path is complete."),
     M("application", "Which action is SAFE?", "unplug a device with dry hands only after an adult has switched off", ["touch a fallen wire", "put a pin in a socket", "fly a kite near power lines"], "Dry hands and adult supervision are safe."),
     TF("approfondissement", "Water is a good insulator, so it is safe to touch a switch with wet hands.", False, "Water with impurities conducts electricity: wet hands near electricity are dangerous."),
     MA("approfondissement", "Match each item with its job.", [("copper wire", "carries electricity"), ("plastic cover", "protects us from shock"), ("cell", "pushes the electricity round"), ("switch", "opens and closes the circuit")], "Each part of a circuit has its own job."),
     P("Ngu sees a broken electric wire lying on the road after a storm. A small child is walking toward it.",
       [PM("What should Ngu do first?", "warn the child to stay away and call an adult", ["pick up the wire with a stick", "touch it to see if it is live", "ignore it"], "Stay away and get help."),
        PM("Why is the wire dangerous?", "it can carry electricity that gives a shock", ["it is heavy", "it makes noise", "it is wet only"], "Electricity can seriously hurt people."),
        PM("Who should repair it?", "the electricity company technicians", ["any child", "a neighbour with a knife", "nobody"], "Only trained people.", points=2)])],
    [("A bulb lights when the circuit is...", "complete", ["broken", "open", "cold"], "A closed path lets electricity flow."),
     ("Which is a good conductor of electricity?", "copper", ["rubber", "plastic", "dry wood"], "Copper is a metal."),
     ("Which should we NEVER do?", "touch a socket with wet hands", ["switch off before cleaning", "ask an adult for help", "keep water away"], "Wet hands are dangerous."),
     ("The part that opens and closes a circuit is the...", "switch", ["cell", "bulb", "plastic"], "The switch controls the path."),
     ("Wires are covered with plastic because plastic is...", "an insulator", ["a conductor", "magnetic", "heavy"], "It protects us.")],
    ["The existing 'Matter and energy' lesson also covers simple circuits; this lesson stresses conductors, insulators and safety. Safety rules are generic and should be reviewed by a qualified person (e.g. an electrician or teacher)."],
    prereq=["fslc-science-matter-energy"])

# =========================================================== chapter 9: materials, environment
ch = p.chapter("materials-environment", "Materials, environment and waste", REF)
fig_mat = grid([("Wood", "hard, burns"), ("Metal", "conducts heat"), ("Plastic", "waterproof"), ("Glass", "transparent"), ("Cloth", "soft, flexible"), ("Rubber", "stretches")], 3, 115, 62)
build(ch, "materials-properties", "Materials and their properties", 30,
    ["Name common materials and their properties.", "Choose a suitable material for a job and give the reason.", "Tell natural from man-made materials and reversible from irreversible changes."],
    [("key", "definition", "Materials", "Everything is made of **materials**. **Natural** materials come from plants, animals or the earth: wood, cotton, wool, leather, clay, stone. **Man-made** materials are made by people: plastic, glass, nylon, cement. Every material has **properties**: hard or soft, rigid or flexible, strong or weak, rough or smooth, waterproof or absorbent, transparent or opaque, conductor or insulator, magnetic or not."),
     ("fig", fig_mat, "Common materials and one property of each.", "Six boxes: wood is hard and burns, metal conducts heat, plastic is waterproof, glass is transparent, cloth is soft and flexible and rubber stretches."),
     ("key", "methode", "Choosing a material", "Ask: what must the object **do**? Then pick the material with the right property. An umbrella needs a **waterproof** cover. A window needs **transparent** glass. A cooking pot needs a **conductor** of heat (metal), but its handle needs an **insulator** (wood or plastic). A towel needs an **absorbent** cloth."),
     ("key", "retenir", "Changes in materials", "In a **reversible** change the material can come back: ice melts to water and water freezes to ice. In an **irreversible** change a **new** material is made and we cannot go back: burning wood, cooking an egg, rusting iron, baking a cake. Heating, cooling and mixing can all cause changes."),
     ("key", "pieges", "Common mistakes", "- Giving a reason that does not match the job (a window made of wood because wood is strong, when we need to see through it).\n- Thinking that all plastics are the same: they differ in strength and flexibility.\n- Saying that melting wax is irreversible: it can go solid again when it cools, so it is reversible."),
     ("ex", "Example 1", "Which material is best for the handle of a kettle: metal, wood or glass? Give a reason.", ["The kettle becomes very hot.", "The handle must not let the heat pass, so we need an insulator.", "Wood (or plastic) is an insulator; metal is a conductor."], "Wood (or plastic), because it is an insulator and stays cool."),
     ("ex", "Example 2", "Say whether each change is reversible or irreversible: (a) ice melting, (b) wood burning.", ["(a) Water can freeze again into ice: reversible.", "(b) Burning wood makes ash and smoke, new materials: irreversible."], "(a) reversible; (b) irreversible.")],
    [M("application", "Which material is waterproof?", "plastic", ["paper", "cotton cloth", "a sponge"], "Plastic does not let water through."),
     M("application", "Which is a natural material?", "cotton", ["plastic", "nylon", "cement"], "Cotton comes from a plant."),
     M("application", "Which property makes glass suitable for windows?", "transparent", ["opaque", "rough", "magnetic"], "We can see through transparent glass."),
     TF("approfondissement", "Burning wood is a reversible change.", False, "Burning makes ash and smoke: new materials that cannot be turned back."),
     MA("approfondissement", "Match the object with the best material.", [("raincoat", "waterproof plastic"), ("window", "clear glass"), ("saucepan", "metal"), ("towel", "absorbent cotton")], "Choose according to the property needed."),
     P("A school needs to make a cover for a notice board that stands outside. The cover must let people read the notice, keep rain out and be strong.",
       [PM("Which property is needed so that people can read the notice?", "transparent", ["opaque", "flexible", "magnetic"], "They must see through the cover."),
        PM("Which property keeps the rain out?", "waterproof", ["absorbent", "soft", "heavy"], "It must not let water through."),
        PM("Which material is the best choice?", "clear plastic or glass", ["cardboard", "cloth", "wood"], "It is transparent and waterproof.", points=2)])],
    [("Which material is flexible?", "rubber", ["stone", "glass", "iron"], "Rubber bends and stretches."),
     ("Which material conducts heat well?", "metal", ["wood", "plastic", "wool"], "Metals are conductors."),
     ("Ice melting is...", "reversible", ["irreversible", "burning", "rusting"], "Water can freeze again."),
     ("Which is a man-made material?", "plastic", ["wool", "wood", "stone"], "Plastic is made in factories."),
     ("An absorbent material...", "soaks up water", ["keeps water out", "is transparent", "is hard"], "A sponge is absorbent.")],
    ["Rusting and egg cooking are given as irreversible changes (standard examples). Floating/sinking and density are intentionally left out."],
    prereq=["fslc-science-matter-energy"])

